WITH flattened AS (SELECT id, service, host, log_ts, latency_ms, status_code, key, attr_value FROM app_logs LATERAL VIEW EXPLODE(context) x AS key, attr_value) SELECT id, service, host, log_ts, key, attr_value, ROUND(latency_ms / SUM(latency_ms) OVER (PARTITION BY service, key), 4) latency_ms_share, ROUND(status_code / SUM(status_code) OVER (PARTITION BY host, key), 4) status_code_share, RANK() OVER w_running status_code_rank, ROW_NUMBER() OVER w_part seq_no FROM flattened WHERE key != 'version' WINDOW w_running AS (PARTITION BY TO_DATE(log_ts), service ORDER BY status_code), w_part AS (PARTITION BY service ORDER BY log_ts, id, key)
